// Milanuncios - enriquecer SIN pedirle nada al portal.
//
// Los otros enriquecedores piden la ficha de cada oferta. Aqui no se puede: las
// fichas de Milanuncios estan detras de Imperva y devuelven 'Pardon Our
// Interruption' con un HTTP 200, no con un error. Se comprobo pidiendo seis con
// quince segundos entre ellas: seis bloqueadas.
//
// Asi que este no tiene nodo HTTP. Lee el texto que ya esta guardado -el titulo,
// la version y la descripcion que el scraper dejo en moveadvisor_offer_texts- y
// deduce de ahi. Eso permite repetirlo cuantas veces haga falta cuando mejoren
// las expresiones, sin esperar a que el scraper vuelva a pasar, que en este
// portal son 68 dias.
//
// Lo que NO hace, porque es de universal-derivar y no tiene sentido tenerlo por
// duplicado: la etiqueta de la DGT, la cilindrada y la traccion. Esas reglas
// valen igual en los once portales.

const filas = $input.all().map(function (x) { return x.json; });
if (!filas.length) return [{ json: { sql: null, count: 0 } }];

function esc(v) {
  if (v === null || v === undefined || v === '') return 'NULL';
  return "'" + String(v).replace(/'/g, "''") + "'";
}

const vals = [];
for (const f of filas) {
  // El titulo y la version primero, la descripcion despues: en el titulo el dato
  // esta puesto por el portal a partir de su ficha, y en la descripcion lo
  // escribe el vendedor a mano. Cuando los dos dicen algo, gana el primero.
  const corto = [f.title, f.version].filter(Boolean).join(' ');
  const texto = [corto, f.descripcion].filter(Boolean).join(' ');
  if (!texto) continue;

  // --- Potencia -----------------------------------------------------------
  // '330cv', '275 HP' y '110kW 150CV'. Se prefiere el CV explicito; si solo hay
  // kW se convierte. El rango descarta que un '2.0' o un año se cuelen.
  let cv = null, kw = null;
  { const m = texto.match(/(\d{2,4})\s*(?:cv|hp)\b/i); if (m) cv = parseInt(m[1], 10); }
  { const m = texto.match(/(\d{2,3})\s*kw\b/i); if (m) kw = parseInt(m[1], 10); }
  if (cv == null && kw != null) cv = Math.round(kw * 1.35962);
  if (kw == null && cv != null) kw = Math.round(cv / 1.35962);
  if (cv != null && (cv < 20 || cv > 1500)) { cv = null; kw = null; }

  // --- Cambio -------------------------------------------------------------
  // Del titulo sale en el 11%; con la descripcion sube al 48%, porque el
  // vendedor lo escribe aunque el portal no lo publique como dato.
  let cambio = '';
  { const m = texto.match(/\b(autom[aá]tic\w*|manual|dsg|s.?tronic|tiptronic|cvt|edc|dct|pdk|steptronic|multitronic)\b/i);
    if (m) cambio = /manual/i.test(m[1]) ? 'Manual' : 'Automatica'; }

  // --- Puertas ------------------------------------------------------------
  let puertas = null;
  { const m = texto.match(/\b([2-5])\s*(?:p|puertas)\b/i); if (m) puertas = parseInt(m[1], 10); }

  // --- Carroceria ---------------------------------------------------------
  // Al vocabulario de la base, no al literal del anuncio: un 'Avant', un
  // 'Variant' o un 'Tourer' son familiares, y guardarlos tal cual crearia
  // carrocerias nuevas que ningun filtro mira.
  //
  // 'Sportback' esta fuera a proposito, y era el termino MAS frecuente: 69
  // apariciones, todas A1 y A3, que son cinco puertas y no coupes. Mapearlo
  // habria sido la principal fuente de carroceria de este portal, y toda mal.
  // Depende del modelo -un A5 Sportback si es otra cosa- y desde el texto no se
  // puede distinguir, asi que se deja vacio. Vacio no engaña a nadie.
  let carroceria = '';
  { const m = texto.match(/\b(berlina|monovolumen|familiar|coup[eé]|cabrio|descapotable|todoterreno|suv|furgoneta|pick.?up|variant|tourer|avant|estate|touring)\b/i);
    if (m) { const v = m[1].toLowerCase().replace(/é/g, 'e');
      if (v === 'berlina') carroceria = 'Berlina';
      else if (v === 'monovolumen') carroceria = 'Monovolumen';
      else if (v === 'familiar' || v === 'variant' || v === 'tourer' || v === 'avant' || v === 'estate' || v === 'touring') carroceria = 'Familiar';
      else if (v === 'coupe') carroceria = 'Coupé';
      else if (v === 'cabrio' || v === 'descapotable') carroceria = 'Descapotable o convertible';
      else if (v === 'suv' || v === 'todoterreno') carroceria = 'SUV';
      else carroceria = 'Furgoneta'; } }

  // --- Color --------------------------------------------------------------
  // Solo de la descripcion, y solo despues de una palabra que anuncie color:
  // 'color', 'pintura' o 'exterior'. Sin eso delante no se coge, porque
  // 'tapiceria negra' y 'llantas negras' no son el color del coche.
  //
  // Se busca el primer color conocido en los 25 caracteres siguientes, y no la
  // palabra pegada a la etiqueta. El formato mas comun es 'Color de pintura:
  // MF01 Blanco', donde el color va tercero: mirando solo la palabra siguiente
  // se leia 'de' y se perdia el dato.
  //
  // Veinticinco y no cuarenta, y cortando en cuanto aparece el interior, por
  // esto, que es literal de un anuncio:
  //
  //   'Color Vulcano Black - Interior en Negro con costuras en Rojo'
  //
  // Con una ventana larga se alcanza ese 'Negro' y se guarda como color del
  // coche cuando es el de la tapiceria. Vulcano Black no lo va a reconocer
  // ninguna lista -son nombres comerciales- y eso no tiene arreglo, pero
  // confundir el interior con la carroceria si lo tiene.
  //
  // Al vocabulario de la base, en singular y con mayuscula inicial.
  let color = '';
  {
    const d = String(f.descripcion || '');
    const m = d.match(/\b(?:color|pintura|exterior)\b/i);
    if (m) {
      let ventana = d.slice(m.index + m[0].length, m.index + m[0].length + 25)
        .toLowerCase()
        .replace(/[áàä]/g, 'a').replace(/[éèë]/g, 'e').replace(/[íìï]/g, 'i')
        .replace(/[óòö]/g, 'o').replace(/[úùü]/g, 'u');
      // Si dentro de la ventana empieza a hablar del interior, se corta ahi.
      const corte = ventana.search(/\b(interior|tapiceri|tapiz|asiento|costura|cuero|tela)/);
      if (corte >= 0) ventana = ventana.slice(0, corte);
      const conocidos = ['blanco','negro','gris','plata','plateado','azul','rojo','verde','amarillo','naranja','marron','beige','dorado','granate','burdeos','violeta','morado'];
      let mejor = null, pos = 1e9;
      for (const k of conocidos) {
        const i = ventana.search(new RegExp('\\b' + k));
        if (i >= 0 && i < pos) { pos = i; mejor = k; }
      }
      if (mejor) color = mejor.charAt(0).toUpperCase() + mejor.slice(1);
    }
  }

  if (cv == null && !cambio && puertas == null && !carroceria && !color) continue;

  vals.push('(' + esc(f.id) + ', ' +
    (cv != null ? cv : 'NULL') + '::int, ' + (kw != null ? kw : 'NULL') + '::int, ' +
    esc(cambio) + '::varchar, ' + (puertas != null ? puertas : 'NULL') + '::int, ' +
    esc(carroceria) + '::varchar, ' + esc(color) + '::varchar)');
}

if (!vals.length) return [{ json: { sql: null, count: 0 } }];

// Un solo UPDATE para todo el lote. Sin nodo HTTP no hay motivo para ir oferta
// por oferta: lo que en los otros enriquecedores son 800 peticiones aqui es una
// consulta.
//
// COALESCE en todos: esto solo rellena huecos. Un valor que ya este puede
// haberlo escrito el scraper, una persona, o una version mejor de estas mismas
// expresiones, y ninguna de las tres se pisa.
//
// Y el '' del final en transmission, body_type y color no es adorno: esas tres
// columnas son NOT NULL con defecto vacio. Sin el, una oferta de la que no se
// saque nada hace reventar el UPDATE entero, con el lote completo dentro.
const sql =
  'UPDATE moveadvisor_market_offers t SET ' +
    'power_cv = COALESCE(t.power_cv, d.cv), ' +
    'power_kw = COALESCE(t.power_kw, d.kw), ' +
    "transmission = COALESCE(NULLIF(t.transmission,''), NULLIF(d.cambio,''), ''), " +
    'doors = COALESCE(t.doors, d.puertas), ' +
    "body_type = COALESCE(NULLIF(t.body_type,''), NULLIF(d.carroceria,''), ''), " +
    "color = COALESCE(NULLIF(t.color,''), NULLIF(d.color,''), ''), " +
    'updated_at = NOW() ' +
  'FROM (VALUES ' + vals.join(', ') + ') AS d(id, cv, kw, cambio, puertas, carroceria, color) ' +
  'WHERE t.id = d.id AND (' +
    // Solo se tocan las filas en las que algo va a cambiar de verdad.
    //
    // Sin esto, como este workflow no lleva marca de 'ya intentado' -para poder
    // repetirlo cuando mejore una expresion- volveria a escribir las mismas
    // filas cada dia, poniendo updated_at = NOW() aunque el COALESCE no cambiara
    // nada. Eso deja miles de ofertas pareciendo modificadas cada mañana y vacia
    // de significado la unica columna que dice cuando cambio algo.
    '(t.power_cv IS NULL AND d.cv IS NOT NULL) OR ' +
    '(t.power_kw IS NULL AND d.kw IS NOT NULL) OR ' +
    "(NULLIF(t.transmission,'') IS NULL AND NULLIF(d.cambio,'') IS NOT NULL) OR " +
    '(t.doors IS NULL AND d.puertas IS NOT NULL) OR ' +
    "(NULLIF(t.body_type,'') IS NULL AND NULLIF(d.carroceria,'') IS NOT NULL) OR " +
    "(NULLIF(t.color,'') IS NULL AND NULLIF(d.color,'') IS NOT NULL)" +
  ')';

return [{ json: { sql: sql, count: vals.length } }];
